# The nullable guard added earlier now only governs the non-trailing case.
old_guard = '''        // A parameter whose default is `null` is php's `?T $x = null`, and php does NOT coerce an
        // explicit null there — it means "no bound", and the builtin reads it as such. The
        // DECLARED type alone cannot tell the two apart: this contract spells the nullable case as
        // `Int` plus a null default, so reading only `param.ty` turned `stream_get_contents($h,
        // null)` into a request for ZERO bytes (it answered `""`) and
        // `stream_copy_to_stream($a, $b, null)` into a copy of nothing, where `php -n` 8.5.6
        // answers the whole stream for both. The coercion below stays for the parameters php
        // really does coerce — a non-nullable scalar, whose default is never null.
        if matches!(param.default, Some(crate::builtins::spec::DefaultSpec::Null)) {
            continue;
        }'''
new_guard = '''        // A parameter php spells `?T $x = null` accepts null as a VALUE; only a non-nullable
